2	module dut(/*AUTOARG*/
3	   // Outputs
4	   dut_active, clkout, wait_out, access_out, packet_out,
5	   // Inputs
6	   clk1, clk2, nreset, vdd, vss, access_in, packet_in, wait_in
7	   );
8	
9	   //##########################################################################
10	   //# INTERFACE 
11	   //##########################################################################
12	
13	   parameter AW    = 32;
14	   parameter ID    = 12'h810;   
15	   parameter S_IDW = 12; 
16	   parameter M_IDW = 6; 
17	   parameter PW    = 2*AW + 40;     
18	   parameter N     = 1;
19	
